-- =====================================================================
-- Manuela 4B MIS - SAMPLE DATA (Jan 2024 - Oct 2026)
-- Streets: Duhat, Santol, Mansanas, Granada, Guyabano, Atis, Ubas
-- Payments: GCash / Maya only (PHP 250 monthly dues). Facilities: Court / Clubhouse only,
-- every reservation is auto-approved and fully paid.
-- Safe to re-run: it first removes earlier sample data (sample_ho* users,
-- *@sample.invalid homeowners, SMP-* receipts). Real records are not touched.
-- BACK UP THE DATABASE FIRST.
-- =====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1) Remove earlier sample data
DELETE FROM payments WHERE receipt_no LIKE 'SMP-%';
DELETE FROM reservations WHERE user_id IN (SELECT id FROM users WHERE username LIKE 'sample_ho%');
DELETE FROM homeowners WHERE email LIKE '%@sample.invalid';
DELETE FROM users WHERE username LIKE 'sample_ho%';

SET @admin_id = (SELECT id FROM users WHERE role = 'admin' ORDER BY id LIMIT 1);

-- 2) Resident accounts (cannot log in: password is not a valid hash)

-- 3) Homeowners (all 7 streets)

-- 4) Helper tables (temporary; dropped at the end)
CREATE TEMPORARY TABLE tmp_sample_ho (n INT PRIMARY KEY, user_id INT, homeowner_id INT);
SELECT CAST(SUBSTRING(u.username, 10) AS UNSIGNED), u.id, h.id FROM users u JOIN homeowners h ON h.user_id = u.id WHERE u.username LIKE 'sample_ho%';

CREATE TEMPORARY TABLE tmp_sample_pay (seq INT PRIMARY KEY, n INT, amt DECIMAL(10,2), pdate DATE, per_cov VARCHAR(20), rcpt VARCHAR(50), pmethod VARCHAR(30), created_ts DATETIME);

CREATE TEMPORARY TABLE tmp_sample_res (seq INT PRIMARY KEY, n INT, facility VARCHAR(100), res_d DATE, st TIME, et TIME, total DECIMAL(10,2), paid DECIMAL(10,2), pstatus VARCHAR(30), popt VARCHAR(30), rstatus VARCHAR(20), created_ts DATETIME);

-- 5) Payments (GCash / Maya only)
SELECT m.homeowner_id, t.amt, t.pdate, t.per_cov, t.rcpt, t.pmethod, @admin_id, NULL, t.created_ts
FROM tmp_sample_pay t JOIN tmp_sample_ho m ON m.n = t.n ORDER BY t.seq;

-- 6) Reservations (Court / Clubhouse)
SELECT m.user_id, t.facility, t.res_d, t.st, t.et, t.total, t.paid, t.pstatus, t.popt, t.rstatus, t.created_ts
FROM tmp_sample_res t JOIN tmp_sample_ho m ON m.n = t.n ORDER BY t.seq;

DROP TEMPORARY TABLE tmp_sample_res;
DROP TEMPORARY TABLE tmp_sample_pay;
DROP TEMPORARY TABLE tmp_sample_ho;

COMMIT;